+                                                                                   Config::Actions::eActionErrorLevel::ERROR, Config::Actions::eActionErrorCode::LUA_ERROR});
+        lua_pop(m_lua, 1);
+        return {.success = false, .error = "lua keybind error"};
+    }
+
+    auto result = dispatchResultFromLua(m_lua, -1);
+    lua_pop(m_lua, 1);
+    return result;
